// === SAFE WEBHOOK READ (try-catch to avoid 'hasn't been executed' error) ===
let rawWebhook = null;
try { rawWebhook = $('Webhook Co Ban').first()?.json; } catch(e) {}
if (!rawWebhook) {
  try { rawWebhook = $('Webhook Nang Cao').first()?.json; } catch(e) {}
}
if (!rawWebhook) {
  try { rawWebhook = $('Webhook RAG').first()?.json; } catch(e) {}
}
if (!rawWebhook) {
  return [{ json: { loi: true, hop_le: false, message: 'Khong tim thay webhook source' } }];
}

const body    = rawWebhook.body    || rawWebhook || {};
const headers = rawWebhook.headers || {};
const query   = rawWebhook.query   || {};

const ApiCode        = (body.ApiCode || query.ApiCode || '').trim();
const isConfirmParam = parseInt(body.isConfirm || query.isConfirm || '0', 10);

if (!ApiCode) return [{ json: { loi: true, hop_le: false, message: 'Thieu ApiCode' } }];

// Doc metadata tu Get API Metadata
const dbItems = $input.all();
if (!dbItems || dbItems.length === 0) {
  return [{ json: { loi: true, hop_le: false, message: 'Khong co metadata (API khong ton tai): ' + ApiCode } }];
}
let metadata = dbItems[0].json;
if (!metadata) {
  return [{ json: { loi: true, hop_le: false, message: 'Metadata null: ' + ApiCode } }];
}
// n8n MSSQL boc trong recordsets
if (metadata.recordsets && metadata.recordsets[0] && metadata.recordsets[0][0]) {
  metadata = metadata.recordsets[0][0];
} else if (metadata.recordset && metadata.recordset[0]) {
  metadata = metadata.recordset[0];
}

if (!metadata || !metadata.StoredProcedure) {
  return [{ json: { loi: true, hop_le: false, message: 'API chua duoc dang ky trong he thong: ' + ApiCode } }];
}

const spName      = metadata.StoredProcedure;
const isConfirmReq = metadata.IsConfirm === true || metadata.IsConfirm === 1;

// === DOC CREDENTIALS ===
const usernameFromQuery  = query.username   || '';
const usernameFromHeader = headers['x-username'] || headers['X-Username'] || '';
const tokenFromQuery     = query.token      || '';
const tokenFromHeader    = headers['authorization'] || headers['Authorization'] || '';

let tokenStr    = tokenFromQuery || tokenFromHeader || body.token || '';
if (tokenStr.startsWith('Bearer ')) tokenStr = tokenStr.slice(7);

let realUsername = usernameFromQuery || usernameFromHeader || body.username || 'UNKNOWN';

// === PARSE JWT ===
let userRoles   = ['USER'];
let isJwtParsed = false;
if (tokenStr && tokenStr !== 'empty' && tokenStr !== 'null' && tokenStr.length > 20) {
  try {
    const parts = tokenStr.split('.');
    if (parts.length === 3) {
      const payload = JSON.parse(Buffer.from(parts[1].replace(/-/g,'+').replace(/_/g,'/'), 'base64').toString('utf-8'));
      let r = payload.role || payload.Role || payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] || 'USER';
      userRoles    = Array.isArray(r) ? r.map(x => String(x).toUpperCase()) : String(r).toUpperCase().split(',');
      realUsername = payload.UserName || payload.username || payload.sub || payload.unique_name || realUsername;
      isJwtParsed  = true;
    }
  } catch(e) {}
}

if (realUsername === 'Demo' || realUsername === 'UNKNOWN') {
  return [{ json: { loi: true, hop_le: false, message: 'Phien dang nhap khong hop le hoac da het han.' } }];
}

// === PARAMS ===
let paramsRaw = body.params || query.params || '{}';
let params = {};
if (typeof paramsRaw === 'string') {
  try { params = JSON.parse(paramsRaw); } catch(e) {}
} else if (typeof paramsRaw === 'object' && paramsRaw !== null) {
  params = paramsRaw;
}

function esc(val) {
  if (val === undefined || val === null || String(val).trim() === '') return 'NULL';
  let str = typeof val === 'object' ? JSON.stringify(val) : String(val);
  return "N'" + str.replace(/'/g, "''") + "'";
}

let sqlArgs = Object.keys(params).map(k => `${k}=${esc(params[k])}`);
sqlArgs.unshift(`@Username=${esc(realUsername)}`);
let sql = `EXEC ${spName} ${sqlArgs.join(', ')};`;

if (isConfirmReq && isConfirmParam === 0) {
  return [{ json: { hop_le: true, need_confirm: true, ApiCode, sql_query: null } }];
}

return [{ json: { hop_le: true, need_confirm: false, ApiCode, sql_query: sql, username: realUsername } }];
